 func updateDesktop(){
 guard !testing,!CommandLine.arguments.contains("--update-test"),desktopEnabled,let image=lastImage else{return};let screens=NSScreen.screens;guard !screens.isEmpty else{return};let screen=screens[min(screenIndex,screens.count-1)]
