 let w=desktopWindow!;w.setFrame(screen.frame,display:true);let view=NSView(frame:NSRect(origin:.zero,size:screen.frame.size));view.wantsLayer=true;let bg=CALayer();bg.frame=view.bounds;bg.contents=image.cgImage(forProposedRect:nil,context:nil,hints:nil);bg.contentsGravity = .resizeAspectFill;bg.masksToBounds=true;view.layer?.addSublayer(bg)
 let text=CATextLayer();text.string=poemText;text.font=CTFontCreateWithName("Songti SC" as CFString,26,nil);text.fontSize=desktopFont;text.alignmentMode=desktopAlign == "center" ? .center : .left;text.foregroundColor=self.desktopColor.cgColor;text.shadowColor=NSColor.black.cgColor;text.shadowOpacity=desktopShadow;text.shadowRadius=6;text.contentsScale=screen.backingScaleFactor;text.isWrapped=true;text.frame=CGRect(x:view.bounds.width*0.57,y:view.bounds.height*0.13,width:view.bounds.width*0.37,height:view.bounds.height*0.7);bg.addSublayer(text);w.contentView=view;w.orderFrontRegardless()
 if CommandLine.arguments.contains("--desktop-test"){print("desktop frame=\(w.frame) screen=\(screen.frame) level=\(w.level.rawValue) ignoresMouseEvents=\(w.ignoresMouseEvents) icon=\(status.button?.image != nil)");fflush(stdout);if let bitmap=view.bitmapImageRepForCachingDisplay(in:view.bounds){view.cacheDisplay(in:view.bounds,to:bitmap);if let data=bitmap.representation(using:.png,properties:[:]){try? data.write(to:URL(fileURLWithPath:FileManager.default.currentDirectoryPath+"/outputs/桌面诗画预览.png"))}};NSApp.terminate(nil)}
 }
 @objc func toggleLogin(){do{if SMAppService.mainApp.status == .enabled{try SMAppService.mainApp.unregister()}else{try SMAppService.mainApp.register()};syncMenuChecks();if SMAppService.mainApp.status == .requiresApproval{SMAppService.openSystemSettingsLoginItems()}}catch{show();let a=NSAlert();a.messageText="登录项设置未完成";a.informativeText="系统返回：\(error.localizedDescription)\n如应用位于外置硬盘，登录时请确保硬盘已挂载。也可在系统设置→通用→登录项中手动添加诗栖。";a.beginSheetModal(for:window)}}
 @objc func menuAction(_ item:NSMenuItem){guard let cmd=item.representedObject as? String else{return};if cmd=="update"{updater.checkForUpdates();return};if ["screensaver","video","stopVideo","screens","desktop","hideDesktop"].contains(cmd){perform(cmd);return};if !["pair","wall","poem","favorite","favoriteWall","copy"].contains(cmd){show()};web.evaluateJavaScript("command('\(cmd)')",completionHandler:nil)}
 func perform(_ cmd:String){
 if cmd=="desktop" {desktopEnabled=true;updateDesktop();window.orderOut(nil)}
 if cmd=="hideDesktop" {desktopEnabled=false;desktopWindow?.orderOut(nil)}
 if cmd=="screensaver" {show();if !screenMode{screenMode=true;web.evaluateJavaScript("if(dialog.open)dialog.close();document.querySelector('header').style.visibility='hidden';document.querySelector('.bar').style.visibility='hidden';toast('屏保模式 · 按 Esc 退出');",completionHandler:nil);window.toggleFullScreen(nil)}}
 if cmd=="rest" {show();NSSound.beep();let a=NSAlert();a.messageText="该休息一下了";a.informativeText="看看远方，活动一下肩颈。诗会在这里等你。";a.addButton(withTitle:"继续阅读");a.beginSheetModal(for:window)}
 if cmd=="screens" {show();let a=NSAlert();a.messageText="选择壁纸显示器";a.informativeText="桌面壁纸与动态壁纸将应用到所选屏幕。";let picker=NSPopUpButton(frame:NSRect(x:0,y:0,width:280,height:30));picker.addItems(withTitles:NSScreen.screens.enumerated().map {"\($0.offset==0 ? "主屏幕" : "显示器 \($0.offset+1)") · \($0.element.localizedName)"});picker.selectItem(at:min(screenIndex,NSScreen.screens.count-1));a.accessoryView=picker;a.addButton(withTitle:"确定");a.addButton(withTitle:"取消");a.beginSheetModal(for:window){r in if r == .alertFirstButtonReturn {self.screenIndex=picker.indexOfSelectedItem;UserDefaults.standard.set(self.screenIndex,forKey:"screenIndex");self.updateDesktop();self.reply("已选择显示器")}}}
 if cmd=="stopVideo" {for p in players{p.pause()};for w in videoWindows{w.orderOut(nil)};for o in loopObservers{NotificationCenter.default.removeObserver(o)};videoWindows=[];players=[];loopObservers=[];videoTexts=[];reply("动态壁纸已停止")}
 if cmd=="video" {show();let panel=NSOpenPanel();panel.allowedContentTypes=[.movie];panel.canChooseDirectories=false;panel.beginSheetModal(for:window){r in guard r == .OK, let url=panel.url else{return};self.perform("stopVideo");let screens=NSScreen.screens;guard !screens.isEmpty else{return};let screen=screens[min(self.screenIndex,screens.count-1)];let w=NSWindow(contentRect:screen.frame,styleMask:.borderless,backing:.buffered,defer:false);w.isReleasedWhenClosed=false;w.level=NSWindow.Level(rawValue:Int(CGWindowLevelForKey(.desktopWindow)));w.collectionBehavior=[.canJoinAllSpaces,.stationary,.ignoresCycle];w.ignoresMouseEvents=true;let view=NSView(frame:NSRect(origin:.zero,size:screen.frame.size));view.wantsLayer=true;let player=AVPlayer(url:url);player.isMuted=true;let layer=AVPlayerLayer(player:player);layer.frame=view.bounds;layer.videoGravity = .resizeAspectFill;view.layer=layer;let text=CATextLayer();text.string=self.poemText;text.font=CTFontCreateWithName("Songti SC" as CFString,28,nil);text.fontSize=28;text.foregroundColor=self.desktopColor.cgColor;text.shadowColor=NSColor.black.cgColor;text.shadowOpacity=0.8;text.shadowRadius=5;text.contentsScale=screen.backingScaleFactor;text.isWrapped=true;text.frame=CGRect(x:screen.frame.width*0.6,y:screen.frame.height*0.18,width:screen.frame.width*0.35,height:screen.frame.height*0.65);layer.addSublayer(text);self.videoTexts.append(text);w.contentView=view;let o=NotificationCenter.default.addObserver(forName:.AVPlayerItemDidPlayToEndTime,object:player.currentItem,queue:.main){_ in player.seek(to:.zero);player.play()};self.loopObservers.append(o);self.players.append(player);self.videoWindows.append(w);w.orderFrontRegardless();player.play();self.reply("动态壁纸已开始，可在菜单中停止")}}
 }
 @objc func show(){window.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
 @objc func about(){let a=NSAlert();a.messageText="诗栖";a.informativeText="一屏山水，一首诗。\n本地诗词与壁纸，无需联网。\n诗词来源：用户提供的《唐诗宋词元曲古文》EPUB。";a.runModal()}
