 func reply(_ text:String){let encoded=String(data:try! JSONSerialization.data(withJSONObject:[text]),encoding:.utf8)!;web.evaluateJavaScript("toast(\(encoded)[0])",completionHandler:nil)}
 func userContentController(_ userContentController:WKUserContentController,didReceive message:WKScriptMessage){
  guard let d=message.body as? [String:String],let action=d["action"] else{return}
  if action=="syncSettings",let raw=d["json"],let data=raw.data(using:.utf8),(try? JSONSerialization.jsonObject(with:data)) is [String:Any] {if !isValidationRun{UserDefaults.standard.set(raw,forKey:"savedState")};syncMenuChecks();return}
  if action=="thumbnail",let name=d["name"],name==URL(fileURLWithPath:name).lastPathComponent,let index=d["index"],let number=Int(index),number>=0,let image=NSImage(contentsOf:resourceRoot.appendingPathComponent("Wallpapers").appendingPathComponent(name)){let small=NSImage(size:NSSize(width:240,height:150));small.lockFocus();image.draw(in:NSRect(x:0,y:0,width:240,height:150));small.unlockFocus();if let tiff=small.tiffRepresentation,let rep=NSBitmapImageRep(data:tiff),let data=rep.representation(using:.jpeg,properties:[.compressionFactor:0.65]){let js="setThumbnail(\(number),'data:image/jpeg;base64,\(data.base64EncodedString())')";web.evaluateJavaScript(js,completionHandler:nil)};return}
  if action=="login"{toggleLogin();return}
  if action=="update"{updater.checkForUpdates();return}
  if action=="loadImage" {guard let name=d["name"],name==URL(fileURLWithPath:name).lastPathComponent else{return};desktopFont=CGFloat(Double(d["size"] ?? "26") ?? 26);desktopAlign=d["align"] ?? "left";desktopShadow=(Float(d["shadow"] ?? "85") ?? 85)/100;desktopColor=NSColor.poetryHex(d["color"] ?? "#fff8e8") ?? desktopColor;poemText=d["text"] ?? poemText;for layer in videoTexts{layer.string=poemText;layer.foregroundColor=desktopColor.cgColor;layer.fontSize=desktopFont;layer.shadowOpacity=desktopShadow;layer.alignmentMode=desktopAlign == "center" ? .center : .left};let url=resourceRoot.appendingPathComponent("Wallpapers").appendingPathComponent(name);do{let data=try Data(contentsOf:url);lastImage=NSImage(data:data);updateDesktop();let mime=name.lowercased().hasSuffix("png") ? "image/png" : "image/jpeg";let values=[name,"data:\(mime);base64,"+data.base64EncodedString()];let json=String(data:try JSONSerialization.data(withJSONObject:values),encoding:.utf8)!;web.evaluateJavaScript("displayImage(...\(json))",completionHandler:nil)}catch{reply("壁纸读取失败：\(error.localizedDescription)")};return}
  if action=="saveOriginal" {guard let name=d["name"],name==URL(fileURLWithPath:name).lastPathComponent else{return};let url=resourceRoot.appendingPathComponent("Wallpapers").appendingPathComponent(name);let panel=NSSavePanel();panel.nameFieldStringValue=name;panel.beginSheetModal(for:window){r in if r == .OK,let dest=panel.url {do{try Data(contentsOf:url).write(to:dest);self.reply("原始壁纸已保存")}catch{self.reply("保存失败：\(error.localizedDescription)")}}};return}
  if testing {if action=="testDone"{print(d["text"] ?? "");fflush(stdout);web.takeSnapshot(with:nil){img,error in if let img=img,let tiff=img.tiffRepresentation,let rep=NSBitmapImageRep(data:tiff),let png=rep.representation(using:.png,properties:[:]){try? png.write(to:URL(fileURLWithPath:FileManager.default.currentDirectoryPath+"/outputs/诗栖预览.png"))};NSApp.terminate(nil)}}else if let raw=d["data"],let comma=raw.firstIndex(of:","),let data=Data(base64Encoded:String(raw[raw.index(after:comma)...])) {try? data.write(to:URL(fileURLWithPath:FileManager.default.currentDirectoryPath+"/outputs/诗画导出验证.png"))};return}
  if ["screensaver","rest","screens","video","stopVideo"].contains(action){perform(action);return}
  if action=="copy" {NSPasteboard.general.clearContents();NSPasteboard.general.setString(d["text"] ?? "",forType:.string);reply("诗词已复制")}
  if action=="wallpaper" || action=="export" || action=="share" {
   guard let raw=d["data"],let comma=raw.firstIndex(of:","),let data=Data(base64Encoded:String(raw[raw.index(after:comma)...])) else{reply("图片生成失败，请重试");return}
   if action=="share" {let url=FileManager.default.temporaryDirectory.appendingPathComponent("诗栖-\(UUID().uuidString).png");do{try data.write(to:url);sharingPicker=NSSharingServicePicker(items:[url]);sharingPicker!.show(relativeTo:NSRect(x:web.bounds.midX,y:100,width:1,height:1),of:web,preferredEdge:.minY)}catch{reply("分享图片生成失败")};return}
   if action=="export" {let panel=NSSavePanel();panel.nameFieldStringValue="诗栖.png";panel.allowedContentTypes=[.png];panel.beginSheetModal(for:window){r in if r == .OK,let url=panel.url {do{try data.write(to:url);self.reply("诗画已保存")}catch{self.reply("保存失败：\(error.localizedDescription)")}}}}
   else {do {let dir=try FileManager.default.url(for:.applicationSupportDirectory,in:.userDomainMask,appropriateFor:nil,create:true).appendingPathComponent("ShiQi",isDirectory:true);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);let url=dir.appendingPathComponent("desktop-\(UUID().uuidString).png");try data.write(to:url);let screens=NSScreen.screens;if !screens.isEmpty{try NSWorkspace.shared.setDesktopImageURL(url,for:screens[min(screenIndex,screens.count-1)],options:[:])};reply("已将诗画设为桌面壁纸")}catch{reply("设置失败：\(error.localizedDescription)")}}
  }
 }
